package com.colonellp.ellamonitor;

import org.json.*;
import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

/** Synthetic period/integral/range checks, independent of Android rendering. */
public class PopupBuild29Test {
    final PopupHistoryTest h=new PopupHistoryTest();
    final MonitorData.Metric load;
    public PopupBuild29Test()throws Exception{load=h.metric("load","electrical","load","");}
    PopupHistory.Plan plan(int p,boolean fixed){return PopupHistory.plan(h.now,h.selection(p,fixed),h.utc);}
    HistoryData.Record scalar(Instant start,int seconds,Double last,Double low,Double high)throws Exception{return new HistoryData.Record(new JSONObject().put("start",start.toString()).put("end",start.plusSeconds(seconds).toString()).put("value",last==null?JSONObject.NULL:last).put("min",low==null?JSONObject.NULL:low).put("max",high==null?JSONObject.NULL:high));}
    @Test public void intervalAmountsUseValidDurationRatherThanNominalBucketWidth()throws Exception{
        for(int seconds:new int[]{3600,86400}){PopupHistory.Plan p=plan(seconds==3600?1:3,true);HistoryData.Record row=h.row(p.query.from,seconds,2,24,900,false);HistoryData.Result data=h.result(load,p,row);
            PopupHistory.Series charge=PopupHistory.series(data,p,"current",false,true),energy=PopupHistory.series(data,p,"watts",false,true);assertEquals("Ah",charge.unit);assertEquals("Wh",energy.unit);assertEquals(.5,charge.points.get(0).value,0);assertEquals(6,energy.points.get(0).value,0);assertFalse(charge.points.get(0).complete);
            assertEquals(SummaryPeriods.totals(data,true).charge,charge.points.get(0).value,0);assertEquals(SummaryPeriods.totals(data,true).energy,energy.points.get(0).value,0);
        }
    }
    @Test public void recordedIntegralsTakePrecedenceOverReintegration()throws Exception{PopupHistory.Plan p=plan(1,true);HistoryData.Record row=h.row(p.query.from,3600,2,24,900,false);row.raw.put("netAh",.49).put("netWh",5.9);HistoryData.Result data=h.result(load,p,row);assertEquals(.49,PopupHistory.series(data,p,"current",false,true).points.get(0).value,0);assertEquals(5.9,PopupHistory.series(data,p,"watts",false,true).points.get(0).value,0);}
    @Test public void absentIntegralsUseIndependentCurrentPowerCoverage()throws Exception{PopupHistory.Plan p=plan(1,true);HistoryData.Record row=h.row(p.query.from,3600,-2,-24,900,false);row.raw.remove("netAh");row.raw.remove("netWh");row.raw.put("powerCoverageSeconds",450);HistoryData.Result data=h.result(load,p,row);assertEquals(.5,PopupHistory.series(data,p,"current",false,true).points.get(0).value,0);assertEquals(3,PopupHistory.series(data,p,"watts",false,true).points.get(0).value,0);}
    @Test public void weekLinesAreSixHoursAndBarsTwelveWithMatchingTotal()throws Exception{PopupHistory.Plan p=plan(2,true);List<HistoryData.Record> rows=new ArrayList<>();for(int i=0;i<24;i++)rows.add(h.row(p.query.from.plusSeconds(i*3600),3600,-2,-24,3600,false));HistoryData.Result data=new HistoryData.Result(load,p.query,rows,h.now.toString());PopupHistory.Series lines=PopupHistory.series(data,p,"current",false,true,false),bars=PopupHistory.series(data,p,"current",false,true,true),sum=PopupHistory.series(data,p,"current",true,true,true);assertEquals(4,lines.points.size());assertEquals(2,bars.points.size());assertEquals(12,lines.points.get(0).value,0);assertEquals(24,bars.points.get(0).value,0);assertEquals(12,Duration.between(bars.points.get(0).start,bars.points.get(0).fullEnd).toHours());assertEquals(24,bars.captured);assertEquals(48,sum.points.get(1).value,0);assertEquals(SummaryPeriods.totals(data,true).charge,sum.points.get(1).value,0);}
    @Test public void missingHoursDoNotBecomeZeroOrACompleteTwelveHourBar()throws Exception{PopupHistory.Plan p=plan(2,true);List<HistoryData.Record> rows=new ArrayList<>();for(int i=0;i<12;i++)if(i!=5)rows.add(h.row(p.query.from.plusSeconds(i*3600),3600,-1,-12,3600,false));PopupHistory.Series s=PopupHistory.series(new HistoryData.Result(load,p.query,rows,h.now.toString()),p,"current",false,true,true);assertEquals(11,s.points.get(0).value,0);assertEquals(11,s.captured);assertFalse(s.points.get(0).complete);assertEquals(12,Duration.between(s.points.get(0).start,s.points.get(0).fullEnd).toHours());}
    @Test public void signedBatteryAndUsageTotalsRemainConsistentAcrossReversals()throws Exception{PopupHistory.Plan p=plan(1,true);HistoryData.Result data=h.result(load,p,h.row(p.query.from,3600,-2,-24,3600,false),h.row(p.query.from.plusSeconds(3600),3600,1,12,3600,false));PopupHistory.Series usage=PopupHistory.series(data,p,"current",true,true),signed=PopupHistory.series(data,p,"current",true,false);assertEquals(3,usage.points.get(1).value,0);assertEquals(-1,signed.points.get(1).value,0);assertEquals(SummaryPeriods.totals(data,true).charge,usage.points.get(1).value,0);assertEquals(SummaryPeriods.totals(data).charge,signed.points.get(1).value,0);assertEquals(-2,data.rows.get(0).value("current","electrical"),0);}
    @Test public void noPowerStaysAbsentWhileCurrentCanStillBeIntegrated()throws Exception{PopupHistory.Plan p=plan(1,true);HistoryData.Record row=h.row(p.query.from,3600,2,24,900,false);row.raw.getJSONArray("values").put(0,JSONObject.NULL);row.raw.put("powerCoverageSeconds",0);HistoryData.Result data=h.result(load,p,row);assertEquals(1,PopupHistory.series(data,p,"current",false,true).points.size());assertTrue(PopupHistory.series(data,p,"watts",false,true).points.isEmpty());assertNull(SummaryPeriods.totals(data,true).energy);}
    @Test public void dayBarsKeepTheWholeHourButOnlyCapturedAh()throws Exception{Instant now=Instant.parse("2026-10-12T00:15:00Z");PopupHistory.Plan p=PopupHistory.plan(now,h.selection(1,false),h.utc);HistoryData.Record row=h.row(p.query.from,3600,2,24,900,true);HistoryData.Result data=new HistoryData.Result(load,p.query,Arrays.asList(row),now.toString());PopupHistory.Point point=PopupHistory.series(data,p,"current",false,true,true).points.get(0);assertEquals(.5,point.value,0);assertEquals(900,Duration.between(point.start,point.end).getSeconds());assertEquals(3600,Duration.between(point.start,point.fullEnd).getSeconds());}
    @Test public void fallBackTwelveHourGroupContainsThirteenRealHours()throws Exception{Instant now=Instant.parse("2026-10-26T12:00:00Z");PopupHistory.Plan p=PopupHistory.plan(now,h.selection(2,true),h.london);List<HistoryData.Record> rows=new ArrayList<>();for(Instant at=p.query.from;at.isBefore(p.query.to);at=at.plusSeconds(3600))rows.add(h.row(at,3600,1,12,3600,false));PopupHistory.Series bars=PopupHistory.series(new HistoryData.Result(load,p.query,rows,now.toString()),p,"current",false,true,true);assertEquals(14,bars.points.size());PopupHistory.Point sunday=bars.points.get(12);assertEquals(13,Duration.between(sunday.start,sunday.fullEnd).toHours());assertEquals(13,sunday.value,0);assertTrue(sunday.complete);assertEquals(169,bars.captured);}
    @Test public void temperatureRangesUseRecordedMinMaxAndWholeWindowExtrema()throws Exception{PopupHistory.Plan p=plan(2,true);MonitorData.Metric temp=h.metric("temp","temperature","","");HistoryData.Result data=h.result(temp,p,scalar(p.query.from,3600,8d,-13d,14d),scalar(p.query.from.plusSeconds(3600),3600,7d,-15d,12d));PopupHistory.Series s=PopupHistory.series(data,p,"temperature",false,false,true);assertTrue(s.temperature);assertEquals(-15,s.minimum,0);assertEquals(14,s.maximum,0);assertEquals(-15,s.points.get(0).low,0);assertEquals(14,s.points.get(0).high,0);assertEquals(7,s.latest,0);assertFalse(PopupHistory.series(data,p,"temperature",true,false,true).cumulative);}
    @Test public void onlyLastTemperatureDoesNotInventAnExtremeRange()throws Exception{PopupHistory.Plan p=plan(1,true);MonitorData.Metric temp=h.metric("temp","temperature","","");PopupHistory.Series s=PopupHistory.series(h.result(temp,p,scalar(p.query.from,3600,12d,null,null)),p,"temperature",false,false,true);assertTrue(s.points.isEmpty());assertNull(s.minimum);assertNull(s.maximum);}
    @Test public void barometerAxisIsFixedEvenWithoutData(){assertArrayEquals(new double[]{900,1100,50},PopupHistory.axisRange(null,true),0);PopupHistory.Series s=new PopupHistory.Series();s.points.add(new PopupHistory.Point(h.now,h.now.plusSeconds(60),1024.5,true));assertArrayEquals(new double[]{900,1100,50},PopupHistory.axisRange(s,true),0);}
    @Test public void temperaturesMayExtendTheZeroOriginAxisBelowZero(){PopupHistory.Series s=new PopupHistory.Series();s.points.add(new PopupHistory.Point(h.now,h.now.plusSeconds(60),h.now.plusSeconds(60),14,true,-15d,14d));double[] range=PopupHistory.axisRange(s,false);assertTrue(range[0]<=-15);assertTrue(range[1]>=14);assertEquals(Math.rint(range[2]),range[2],0);}
    @Test public void dayTicksOmitMinutesAndNameEndMidnightTwentyFour(){PopupHistory.Plan p=plan(1,true);assertEquals("0",PopupHistory.dayTick(p.query.from,p));assertEquals("2",PopupHistory.dayTick(p.query.from.plusSeconds(7200),p));assertEquals("24",PopupHistory.dayTick(p.end,p));}
    @Test public void refreshTracksMinuteHourDayWeekAndMonthBoundaries(){assertEquals(Instant.parse("2026-10-12T13:02:00Z"),PopupHistory.nextRefresh(h.now,h.selection(0,false),h.utc));assertEquals(Instant.parse("2026-10-12T14:00:00Z"),PopupHistory.nextRefresh(h.now,h.selection(0,true),h.utc));for(int p:new int[]{1,2})assertEquals(Instant.parse("2026-10-12T14:00:00Z"),PopupHistory.nextRefresh(h.now,h.selection(p,false),h.utc));assertEquals(Instant.parse("2026-10-13T00:00:00Z"),PopupHistory.nextRefresh(h.now,h.selection(3,false),h.utc));assertEquals(Instant.parse("2026-10-13T00:00:00Z"),PopupHistory.nextRefresh(h.now,h.selection(1,true),h.utc));assertEquals(Instant.parse("2026-10-19T00:00:00Z"),PopupHistory.nextRefresh(h.now,h.selection(2,true),h.utc));assertEquals(Instant.parse("2026-11-01T00:00:00Z"),PopupHistory.nextRefresh(h.now,h.selection(3,true),h.utc));PopupSelection old=h.selection(3,true);old.month="2025-09";assertNull(PopupHistory.nextRefresh(h.now,old,h.utc));}
    @Test public void midnightRefreshRespectsTwentyThreeHourDstDay(){Instant now=Instant.parse("2026-03-29T00:00:00Z");assertEquals(Instant.parse("2026-03-29T23:00:00Z"),PopupHistory.nextRefresh(now,h.selection(1,true),h.london));}
    @Test public void incompleteFixedCheckpointIsDistinguishedFromRollingData()throws Exception{PopupHistory.Plan p=plan(0,true);HistoryData.Result data=new HistoryData.Result(load,p.query,Collections.emptyList(),p.query.to.minusSeconds(5).toString());assertTrue(PopupHistory.awaitingFinalCheckpoint(data,h.selection(0,true)));assertFalse(PopupHistory.awaitingFinalCheckpoint(data,h.selection(0,false)));assertFalse(PopupHistory.awaitingFinalCheckpoint(new HistoryData.Result(load,p.query,Collections.emptyList(),p.query.to.toString()),h.selection(0,true)));}
    @Test public void valuesDefaultsOnAndRoundTripsIndependently()throws Exception{assertTrue(PopupSelection.parse(new JSONObject()).values);PopupSelection state=h.selection(2,true);state.values=false;state.power=true;PopupSelection restored=PopupSelection.parse(state.json());assertFalse(restored.values);assertTrue(restored.power);try{PopupSelection.parse(state.json().put("values","false"));fail();}catch(IllegalArgumentException expected){}}
    @Test public void graphAxesThemeRoleCopiesSavesAndInheritsOldLabels()throws Exception{ThemeConfig t=ThemeConfig.defaults();t.name="Graph test";int controls=t.controls;t.set(ThemeConfig.GRAPH_AXES,0xff123456);assertEquals(0xff123456,t.get(ThemeConfig.GRAPH_AXES));assertEquals(controls,t.controls);assertEquals(t.graphAxes,t.copy().graphAxes);assertEquals(t.graphAxes,ThemeConfig.validatedSaved(t.toJson()).graphAxes);JSONObject older=t.toJson();older.remove(ThemeConfig.GRAPH_AXES);assertEquals(t.text,ThemeConfig.fromJson(older).graphAxes);assertFalse(t.sameColours(ThemeConfig.defaults()));}
}
